package br.com.fatura;
import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.*;import org.springframework.security.web.csrf.CsrfToken;import org.springframework.security.crypto.password.PasswordEncoder;import jakarta.validation.*;import jakarta.validation.constraints.*;import java.security.Principal;import java.util.*;import java.time.*;import java.math.*;import com.google.zxing.*;import com.google.zxing.client.j2se.MatrixToImageWriter;import java.io.*;
@RestController @RequestMapping("/api") class Api {
final Users users;final Bills bills;final PasswordEncoder encoder;Api(Users u,Bills b,PasswordEncoder e){users=u;bills=b;encoder=e;}
record Registration(@NotBlank @Size(max=100) String name,@Email @NotBlank @Size(max=254) String email,@NotBlank @Size(min=12,max=72) String password){}
record Input(@NotBlank @Size(max=120) String title,@NotBlank @Size(max=50) String category,@NotNull @DecimalMin("0.01") @Digits(integer=12,fraction=2) BigDecimal amount,@NotNull LocalDate due,@Min(0) @Max(30) int reminderDays,@Size(max=512) String paymentCode,@NotNull String paymentType,@Size(max=200) String source){}
@GetMapping("/csrf") Map<String,String> csrf(CsrfToken t){return Map.of("token",t.getToken(),"header",t.getHeaderName());}
@PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) void register(@Valid @RequestBody Registration r){if(r.password().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>72)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Senha deve ter até 72 bytes UTF-8");AppUser u=new AppUser();u.name=r.name().trim();u.email=r.email().trim().toLowerCase();u.password=encoder.encode(r.password());try{users.saveAndFlush(u);}catch(org.springframework.dao.DataIntegrityViolationException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"Cadastro indisponível para esse e-mail");}}
AppUser owner(Principal p){return users.findByEmail(p.getName()).orElseThrow();}
@GetMapping("/me") Map<String,String> me(Principal p){AppUser u=owner(p);return Map.of("name",u.name,"email",u.email);}
@GetMapping("/bills") List<Bill> list(Principal p){return bills.findByOwnerIdOrderByDueAsc(owner(p).id);}
Bill owned(UUID id,Principal p){return bills.findByIdAndOwnerId(id,owner(p).id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}
@PostMapping("/bills") Bill add(@Valid @RequestBody Input i,Principal p){Bill b=new Bill();b.ownerId=owner(p).id;return save(b,i);}
@PutMapping("/bills/{id}") Bill update(@PathVariable UUID id,@Valid @RequestBody Input i,Principal p){return save(owned(id,p),i);}
Bill save(Bill b,Input i){if(!Set.of("NONE","PIX","BARCODE").contains(i.paymentType()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);if(!i.paymentType().equals("NONE")&&(i.source()==null||i.source().isBlank()||i.paymentCode()==null||i.paymentCode().isBlank()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Informe o código original e a origem");if(i.paymentType().equals("BARCODE")&&!i.paymentCode().matches("[0-9 .-]{44,80}"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);b.title=i.title();b.category=i.category();b.amount=i.amount();b.due=i.due();b.reminderDays=i.reminderDays();b.paymentType=i.paymentType();b.paymentCode=i.paymentCode();b.source=i.source();b.lastReminded=null;return bills.save(b);}
@PostMapping("/bills/{id}/paid") Bill paid(@PathVariable UUID id,Principal p){Bill b=owned(id,p);b.paid=!b.paid;return bills.save(b);}
@DeleteMapping("/bills/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable UUID id,Principal p){bills.delete(owned(id,p));}
@GetMapping(value="/bills/{id}/qr",produces="image/png") byte[] qr(@PathVariable UUID id,Principal p)throws Exception{Bill b=owned(id,p);if(!"PIX".equals(b.paymentType)||b.paymentCode==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST);ByteArrayOutputStream out=new ByteArrayOutputStream();MatrixToImageWriter.writeToStream(new MultiFormatWriter().encode(b.paymentCode,BarcodeFormat.QR_CODE,320,320),"PNG",out);return out.toByteArray();}
}
